import datetime
import kiln


def count_in_january(ledger, year) -> int:
    """Count ledger entries dated in January of the given year."""
    start = datetime.date(year, 1, 1)
    end = datetime.date(year, 1, 31)
    return sum(1 for _date, _account, _amount in ledger.between(start, end))

import datetime
import kiln


def year_total(ledger, account, year) -> int:
    """Return total amount posted to `account` during calendar year `year`."""
    start = datetime.date(year, 1, 1)
    end = datetime.date(year, 12, 31)
    total = 0
    for _date, acct, amount in ledger.between(start, end):
        if acct == account:
            total += amount
    return total

import datetime


def has_activity(ledger, day: datetime.date) -> bool:
    """Return True iff the ledger has at least one entry on the given day."""
    # Prefer a targeted query if available.
    # The kiln API specifies `between(start, end)` inclusive of those dates.
    try:
        start = day
        end = day
        return len(ledger.between(start, end)) > 0
    except Exception:
        # Fallback: scan all entries.
        for d, _account, _amount in getattr(ledger, "entries")():
            if d == day:
                return True
        return False

import datetime
import kiln


def range_total_dollars(ledger, account, first_day, last_day) -> float:
    """Return the total posted to `account` from `first_day` to `last_day` inclusive.

    Assumes ledger entries use integer amounts representing cents (as typical
    for kiln.fee/fee rates). The result is returned in dollars as a float.
    """
    # Ensure inputs are datetime.date
    if isinstance(first_day, datetime.datetime):
        first_day = first_day.date()
    if isinstance(last_day, datetime.datetime):
        last_day = last_day.date()

    if not isinstance(first_day, datetime.date) or not isinstance(last_day, datetime.date):
        raise TypeError("first_day and last_day must be datetime.date")

    total_cents = 0
    for date, acc, amount in ledger.between(first_day, last_day):
        if acc == account:
            total_cents += amount

    return total_cents / 100.0

import kiln


def first_item(shelf):
    """Return the item in the first slot of the given shelf."""
    return shelf.get(0)

import kiln


def last_item(shelf):
    """Return the item in the last slot of `shelf`."""
    return shelf.get(shelf.size - 1)

