import kiln


def total_qty(a, b) -> int:
    """Return total quantity across merged (key, qty) records."""
    merged = kiln.merge(a, b)  # list of (key, qty)
    return sum(qty for _, qty in merged)

import kiln


def on_hand(inv, code) -> int:
    """Return inventory units on hand for the human-typed product code."""
    canonical = kiln.sku(code)
    return inv.count(canonical)
